func (t FlowNode) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t FlowNode) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "assert":
		return t.AsAssertFlowNode()
	case "branch":
		return t.AsBranchFlowNode()
	case "delay":
		return t.AsDelayFlowNode()
	case "loop":
		return t.AsLoopFlowNode()
	case "module":
		return t.AsModuleFlowNode()
	case "poll":
		return t.AsPollFlowNode()
	case "request":
		return t.AsRequestFlowNode()
	case "set_variable":
		return t.AsSetVariableFlowNode()
	case "sse":
		return t.AsSseFlowNode()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

